// Generated by scripts/build-offline.mjs. Do not edit sw.js directly.
const VERSION = '__VERSION__';
// Namespace by scope so another Squarez install on this origin isn't affected.
const PREFIX = `squarez:${self.registration.scope}:`;
const CACHE = PREFIX + VERSION;
const ASSETS = __ASSETS__;
const URLS = ASSETS.map(p => new URL(p, self.registration.scope).href);
const INDEX = new URL('index.html', self.registration.scope).href;

self.addEventListener('install', event => {
  // addAll is atomic: don't activate a version with missing assets. Failed installs retry online.
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(
    URLS.map(url => new Request(url, { cache: 'reload' }))
  )));
  // No skipWaiting: existing tabs finish using their current game version.
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith(PREFIX) && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (!url.href.startsWith(self.registration.scope)) return;
  // Serve only the app's entry routes as navigation, not unrelated paths within the scope.
  const entry = url.pathname === new URL(self.registration.scope).pathname
    || url.pathname === new URL(INDEX).pathname;
  const key = request.mode === 'navigate' && entry ? INDEX : url.href;
  if (!URLS.includes(key)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    return await cache.match(key) || fetch(request);
  })());
});
